-- ============================================
-- LUMA — Enrichissement Thématique 7 (Shopping) : scénarios longs
-- ============================================

update scenarios set content = '{"characters": {"friend": "ton ami(e)"}, "start_node": "n1", "nodes": {"n1": {"speaker": "friend", "text": "Where should we start, shoes or clothes?", "text_fr": "On commence par où, chaussures ou vêtements ?", "choices": [{"text": "Let''s do shoes first, I need new sneakers.", "next": "n2"}, {"text": "Clothes first, I want to check the new collection.", "next": "n2b"}, {"text": "Let''s just wander and see what catches our eye.", "next": "n2c"}]}, "n2": {"speaker": "friend", "text": "These sneakers look great on you! What do you think?", "text_fr": "Ces baskets te vont super bien ! Qu''en penses-tu ?", "choices": [{"text": "I love them, let''s get these.", "next": "n3"}, {"text": "They''re nice, but a bit over my budget.", "next": "n3b"}]}, "n2b": {"speaker": "friend", "text": "This jacket would look amazing with your style.", "text_fr": "Cette veste irait super bien avec ton style.", "choices": [{"text": "You''re right, let''s try it on.", "next": "n3"}]}, "n2c": {"speaker": "friend", "text": "Ooh, this vintage shop looks interesting, let''s check it out.", "text_fr": "Ooh, cette boutique vintage a l''air intéressante, allons voir.", "choices": [{"text": "I love a good surprise find.", "next": "n3"}]}, "n3": {"speaker": "friend", "text": "Okay, one more stop — the accessories shop?", "text_fr": "D''accord, un dernier arrêt — la boutique d''accessoires ?", "choices": [{"text": "Sure, let''s see what they have.", "next": "n4"}]}, "n3b": {"speaker": "friend", "text": "Let''s check if there''s a sale or a similar cheaper option.", "text_fr": "Regardons s''il y a une promo ou une option similaire moins chère.", "choices": [{"text": "Good idea, let''s compare before deciding.", "next": "n4"}]}, "n4": {"speaker": "friend", "text": "This has been such a productive shopping trip!", "text_fr": "Cette session shopping a été super productive !", "choices": [{"text": "Definitely, I found everything I needed.", "next": "n5"}, {"text": "Honestly, I think I overspent a little.", "next": "n5b"}]}, "n5": {"speaker": "friend", "text": "Time for coffee to celebrate our finds!", "text_fr": "L''heure du café pour célébrer nos trouvailles !", "choices": [{"text": "Absolutely, we deserve it.", "next": "end_success"}]}, "n5b": {"speaker": "friend", "text": "Happens to the best of us, at least everything was worth it!", "text_fr": "Ça arrive aux meilleurs, au moins tout en valait la peine !", "choices": [{"text": "True, I''ll budget better next time.", "next": "end_learned"}]}, "end_success": {"speaker": "friend", "text": "Best shopping day in a while!", "text_fr": "Meilleure journée shopping depuis longtemps !", "end": true, "ending_label": "Journée shopping réussie 🛍️"}, "end_learned": {"speaker": "friend", "text": "That''s the spirit — a good lesson wrapped in a fun day.", "text_fr": "Voilà l''esprit — une bonne leçon dans une journée sympa.", "end": true, "ending_label": "Journée shopping riche en leçons 💡"}}}'::jsonb, is_playable = true
where title = 'Une session shopping avec plusieurs boutiques et décisions'
  and theme_id = (select id from scenario_themes where position = 7 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"agent": "l''agent du service client"}, "start_node": "n1", "nodes": {"n1": {"speaker": "agent", "text": "How can I help you today?", "text_fr": "Comment puis-je vous aider aujourd''hui ?", "choices": [{"text": "I was charged twice for the same order, I''d like a refund.", "next": "n2"}, {"text": "This is the second time this has happened, I''m quite frustrated.", "next": "n2b"}]}, "n2": {"speaker": "agent", "text": "I''m sorry about that. Let me pull up your order details.", "text_fr": "Désolé pour ce désagrément. Laissez-moi consulter votre commande.", "choices": [{"text": "Thank you, here''s my order number.", "next": "n3"}]}, "n2b": {"speaker": "agent", "text": "I completely understand your frustration, and I apologize for the repeated issue. Let''s fix this properly.", "text_fr": "Je comprends totalement votre frustration, et je m''excuse pour ce problème répété. Réglons ça correctement.", "choices": [{"text": "I appreciate that, here''s my order number.", "next": "n3"}]}, "n3": {"speaker": "agent", "text": "I see the duplicate charge, I''ll refund it right away.", "text_fr": "Je vois le double prélèvement, je vous rembourse tout de suite.", "choices": [{"text": "I appreciate the quick resolution.", "next": "n4"}, {"text": "Could you also make sure this doesn''t happen again?", "next": "n4b"}]}, "n4": {"speaker": "agent", "text": "You should see the refund in 3-5 business days.", "text_fr": "Vous devriez voir le remboursement sous 3 à 5 jours ouvrés.", "choices": [{"text": "Perfect, thank you for your help.", "next": "end_resolved"}]}, "n4b": {"speaker": "agent", "text": "I''ll flag your account to prevent this billing issue going forward.", "text_fr": "Je vais signaler votre compte pour éviter ce problème de facturation à l''avenir.", "choices": [{"text": "That''s exactly what I needed to hear, thank you.", "next": "end_prevented"}]}, "end_resolved": {"speaker": "agent", "text": "Sorry again for the inconvenience, have a great day!", "text_fr": "Encore désolé pour ce désagrément, bonne journée !", "end": true, "ending_label": "Litige résolu 💳"}, "end_prevented": {"speaker": "agent", "text": "You''re all set, and this shouldn''t recur. Thank you for your patience.", "text_fr": "Tout est réglé, et ça ne devrait plus se reproduire. Merci pour votre patience.", "end": true, "ending_label": "Problème résolu durablement 🛡️"}}}'::jsonb, is_playable = true
where title = 'Un litige avec le service client'
  and theme_id = (select id from scenario_themes where position = 7 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"stylist": "la conseillère en image"}, "start_node": "n1", "nodes": {"n1": {"speaker": "stylist", "text": "So, what''s the event and what vibe are you going for?", "text_fr": "Alors, c''est quel événement et quelle ambiance tu recherches ?", "choices": [{"text": "A wedding, I want something elegant but not too formal.", "next": "n2"}, {"text": "A job interview, I need to look professional and confident.", "next": "n2b"}, {"text": "Honestly, I have no idea, I need real guidance.", "next": "n2c"}]}, "n2": {"speaker": "stylist", "text": "This navy suit with a lighter shirt would be perfect.", "text_fr": "Ce costume bleu marine avec une chemise plus claire serait parfait.", "choices": [{"text": "I love that combination, let''s go with it.", "next": "n3"}]}, "n2b": {"speaker": "stylist", "text": "A tailored blazer with simple, clean lines would work great.", "text_fr": "Un blazer ajusté avec des lignes simples et nettes fonctionnerait très bien.", "choices": [{"text": "That sounds exactly right for the tone I want.", "next": "n3"}]}, "n2c": {"speaker": "stylist", "text": "No worries, let''s start with your comfort level — bold colors or classic neutrals?", "text_fr": "Pas de souci, commençons par ton niveau de confort — couleurs vives ou neutres classiques ?", "choices": [{"text": "Classic neutrals, I feel more like myself in those.", "next": "n3b"}]}, "n3": {"speaker": "stylist", "text": "Let''s add the right accessories to complete the look.", "text_fr": "Ajoutons les bons accessoires pour compléter le look.", "choices": [{"text": "Perfect, I trust your judgment here.", "next": "n4"}]}, "n3b": {"speaker": "stylist", "text": "Great instinct — let''s build a full outfit around that comfort zone.", "text_fr": "Bon instinct — construisons une tenue complète autour de cette zone de confort.", "choices": [{"text": "I like where this is going.", "next": "n4"}]}, "n4": {"speaker": "stylist", "text": "(final fitting) How does everything feel together?", "text_fr": "(essayage final) Comment tu te sens dans tout ça ?", "choices": [{"text": "Honestly, I feel like the best version of myself.", "next": "end_complete"}, {"text": "Great, though could we adjust the shoes slightly?", "next": "end_adjusted"}]}, "end_complete": {"speaker": "stylist", "text": "You''re going to look fantastic!", "text_fr": "Tu vas être fantastique !", "end": true, "ending_label": "Garde-robe complète et parfaite 👔"}, "end_adjusted": {"speaker": "stylist", "text": "Of course, small details make a big difference. Let''s find the perfect pair.", "text_fr": "Bien sûr, les petits détails font une grande différence. Trouvons la paire parfaite.", "end": true, "ending_label": "Garde-robe peaufinée dans les détails ✨"}}}'::jsonb, is_playable = true
where title = 'Préparer une garde-robe pour un événement'
  and theme_id = (select id from scenario_themes where position = 7 and language_id = (select id from languages where code = 'en'));
